/* Founder planning artifact only. Generates static, local interaction studies; no SDK/account data. */
const fs = require('fs');
const path = require('path');
const esc = s => String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const rooms = [
  {id:'sky',name:'Sky',title:'An almanac you can use',species:'Morning glory',material:'Living canopy → printed sky → a personal notebook',pair:'Ask the sky / Edit your chart; incomplete chart gets the real setup pair.',
   order:['Your dated forecast, complete','One daily lesson clearing','Chart, bench and observed Moon history','The two independent tides','Year, earlier skies and private notes','Questions, pairing and correspondence','Quiet / soft settings and evidence'],
   why:'Reading now, a small discovery, then the deeper chart. Personal history is distinct from public teaching; every movement stays on the continuous Lifestyle page.',
   setup:'A usable chart leads with the actual reading date, not merely today’s header date. No birth time: explain what can still be read and what needs it. No chart: keep factual Moon/lessons useful while the direct setup action opens the existing sheet. Loading never masquerades as missing details.',
   anatomy:[['Forecast','Date and authored title above the full reading. Keep its music, Share, Reflect, Lounge, Jess and Mark read. Power / Pressure / Trouble form three directed editorial entries, with a short label and full text. No new three-tab gate.'],['Daily learning','The five manual slides keep source, date, Previous / Next, Keep and private-note action. A single tissue fold marks the edge; the number means the actual lesson position. Help explains the current idea in place. The eight-phase instrument remains separate from the daily deck.'],['Chart and setup','Sun / Moon / Rising are full-width expandable rows, not three narrow reading columns. Keep real degrees, element, ruler, birth details and all bench readings. Fields stack on phones; birth time is optional where the existing calculation allows it.'],['Tides and diary','Lunar illumination and cycle date are independently labelled. Logged starts show measured phase counts and sample size. Earlier forecasts keep dates; current notebook draft and previous notes stay accessible. No invented synchrony, personality or hidden full history.'],['Ask / pairing','One obvious question field with suggested questions and prior answers. Pairing labels both people, validates calendar dates and makes the actual link payload visible before copying. Preserve the four dimensions and full answer; no new compatibility score.'],['Letters / controls','Published owner letter or honest empty state, real date and attribution. Existing products remain available without new sales pressure. Preferences show saving/failure on the affected row; important astronomy/symbolism distinction stays visible.']],
   craft:'Open writing dominates. A tiny orbital index belongs to the phase instrument; a petal-vein seam belongs to learning; a fallen fragment belongs beside the dated notebook. The Moon never becomes a second hero and brass/printed instruments do not wobble. Help dots have large real targets.',
   copy:['“A little sky wisdom.”','“One line for your notebook?”','“The sky has notes. You have the deciding vote.”'],
   atoms:[['SK1','First-fold specificity','Owner reading + AstroProfile + actual date feed the glance and authored Jess template. No reading: say that and retain teaching. Refresh both after chart change; previous owner clears immediately.'],['SK2','Lesson term → useful help','Bind the rosette to the selected lesson/phase. Expanded text sits beneath that term and does not hide controls or the full forecast. Arrow/swipe/date-change keep exact version and active draft.'],['SK3','Reflection → the same note','Existing JournalEntries / SkyNote stores retain their different meanings. Implement an owner-checked exact entry return; a generic Journal landing is not “Open this note”. Pending, failed and retained-draft states are distinct.'],['SK4','Read → an honest Garden record','Exact reading ID + date, not one permanent chapter key. Readback agrees after remount; a failed remote record cannot be announced as cross-device confirmation. Do not auto-complete from scrolling.'],['SK5','Public lesson → editable conversation','Keep title/versioned source URL public; private chart, cycle and reflection stay separate. Reuse the actual lounge composer, consented post-to-DM request and participant message flow. Verify reply → original lesson, block/report and deleted source.'],['SK6','Earlier answers / two identities','Audit full answers, future/invalid birth dates, Unicode link roundtrip and copy failure. Submitted question is retained on error. Sharing restores inputs only unless actual published answer access is supported.'],['SK7','Settings / letter integrity','Read newest actual owner preference row; await confirmed writes with rollback. Published letter sanitisation and AI-assisted attribution remain. Conditional/no-letter/unavailable product states are tested without fabricating a letter.']],
   first:'SK2 — the current lesson and its meaning dot, with exact keep and reflection states.',
   states:'First visit / no chart / unknown birth time / real dated reading / archived lesson / midnight with draft / failed save / another owner / unpublished letter.'},
  {id:'read',name:'Read',title:'An editorial desk, not a feed',species:'Iris',material:'Vellum threshold → a bookmarked reading margin → fiction',pair:'Choose a read / Saved reads; real continuation may make the first action Resume [short title].',
   order:['A real unfinished read, when there is one','The editorial lead, kept available even when resuming','Fresh essays and guides with varied life subjects','Stories and fiction with their own reading rhythm','Useful exact-object connections at the relevant item'],
   why:'Return to her actual place first. Then introduce something worth beginning. Fiction is a different pleasure, not another clinical article in the same stack.',
   setup:'No onboarding questionnaire before reading. Existing interests can influence order only if the feed actually uses them. Anonymous readers can consume public content; a save tells them sign-in is needed. No prior place means a fresh lead, not an invented continuation.',
   anatomy:[['Resume strip','An actual title, source/edition and stored place with one direct Resume. A ribbon marks this saved place, not a progress reward. The current article page index is not yet a robust cross-device paragraph anchor; the interface must name only what it stores.'],['Leading essay','One generous headline and a short real source excerpt. Author, editorial source and verified duration appear once. Open reaches the actual full item; Keep is a distinct control. Full article text remains intact, including paragraph breaks and links.'],['Fresh reads','Open editorial entries with varied headline lengths and occasional meaning rosette. Topic/source earns its place; no repeated “A few minutes” placeholder. Health remains, alongside relationships, work, money, creativity and entertainment when real content exists.'],['Fiction','A chapter-leaf treatment with a real first line and author/series identity. Stories use indent-without-extra-gap; essays use paragraph spacing. Full readers and saved place remain. No invented book cover or fake serial release.'],['Within the reader','One padding owner for reading measure; accessible close/settings/bookmark above tap zones. Selection, if implemented, retains version + passage context. Resume is separate from explicitly completed. Closing returns to the same item and scroll position.'],['Contextual action','A selected public idea can enter an editable Community draft or Jess question with exact source. Her own annotation is private until explicitly included. No generic related-by-phase strip or five social actions on every row.']],
   craft:'The leading essay is a clear white folio. Continuation uses a functional bookmark; fresh entries are open; fiction gets a quiet chapter opening. One iris-veined edge carries into the lead and a thin pressed trace marks the fiction seam. No flower-sized column steals the prose width.',
   copy:['“Back to that good bit.” — only with a stored place','“A rabbit hole, with better punctuation.”','“Not saved yet. Try again.”'],
   atoms:[['RD1','A genuine content lead','Reconcile the existing personalised feed and engagement library. Rank actual eligible items, retain editorial choice and expose an honest reason only from real inputs. Test an empty library and a one-topic-heavy set; never invent whole-life inventory.'],['RD2','Exact continuation','Distinguish book/fiction reader positions from local article page indices. Keep content ID/version/last location; cross-device paragraph continuation needs a separate storage decision. Last place ≠ furthest reached ≠ finished.'],['RD3','Paragraphs survive opening','Full LifestyleDetail → typed reading pane must preserve blocks, quotations, inline links and headings. No flattening all paragraphs into one string. Test a real multi-paragraph article, revised source and long title.'],['RD4','Keep / unkeep tells the truth','Existing UserProfile save IDs await acknowledgement, with one pending action per object, retained intent on failure and no “Saved” for no-auth. Yours and full Saved reconcile afterwards; no new third save store.'],['RD5','A passage with provenance','Optional quote/prefix/suffix + content version where rights allow. Ambiguous/revised passage keeps the note and exposes a recoverable source state. Private reflection never becomes a public post automatically.'],['RD6','One useful conversation','Public exact article/selected passage → editable existing composer → consented conversation → original item. Jess receives source and her actual question, not an invented recap about her.'],['RD7','Whole-life voice / metadata','Audit source titles, short excerpts and medically absolute wording separately. Keep complete existing articles; editorial corrections retain version history. No copy budget can silently delete substance.']],
   first:'RD3 / RD4 reliability, then RD1 / RD2 bookmark-led desk.',
   states:'No history / one unfinished item / source updated / content removed / save pending / failure / signed out / long title / no suitable fresh content.'},
  {id:'listen',name:'Listen',title:'A sound room with a real programme',species:'Bluebell',material:'Acoustic pleats → one living player → programme slips → a watch clearing',pair:'Choose a listen / Choose a watch; a paused episode may give a direct Resume action after proof.',
   order:['The actual active or paused episode','A new editorial listen, still available','Programme rows grouped by real show/subject','A visibly different watch movement','Transcripts and source depth beside their item'],
   why:'Sound is an activity, not a list of cover cards. The transport owns the first useful space; programme rows suggest what follows, while video retains its own poster and watch behaviour.',
   setup:'Play needs no preference interview. Existing PodcastListens and singleton playback context can provide a real position. Resolve metadata before seeking; loading, buffering and playing are different. An external-only show opens its actual show page and is never advertised as playable inside FemWell.',
   anatomy:[['The player','Title/show and verified duration once, then large Play / Pause, accessible seek/skip and current position. Unmeasured time stays unknown. A small playing indicator may move only with actual playback; it freezes while paused/buffering/reduced motion.'],['Paused versus featured','Returning audio gets the lead, but today’s editorial choice stays as a smaller direct programme entry. Stop the old item when selecting a new one. Saving an episode does not mean listened; seeking does not mean finished.'],['Programme','Compact show rows: actual episode title, supplied date, source, duration and a short genuine excerpt. Same source is not repeated as two leads. Programme order explains chronology/subject rather than pretending personalised ranking.'],['Chapters / transcript','Use supplied timestamps or authored segments when they exist. A coherent short segment can fit spare time, clearly labelled as part of a longer episode. An untimed transcript is readable but cannot pretend to seek; a synopsis is not a transcript.'],['Watch','A wider poster and direct real video play. No “A short listen” on a video. Preserve details, source link, caption availability and watch directory. Removed/private/unembeddable content keeps a useful source escape and error.'],['A moment shared','A deliberate episode + timestamp can become a public conversation reference. Preview what will open for the recipient, and offer the full episode when segment precision is unsupported. Existing consented DM, not new arbitrary-recipient chat.']],
   craft:'Transport sits in a low, open acoustic console; programme rows share one aligned title/source rail. Watches get a genuine screen silhouette. A bluebell curve meets the housing seam once; one fine acoustic pleat carries down to transcript, never a fake random waveform.',
   copy:['“Back where you paused.”','“Listen here” / “Open the show” reflect actual capability','“Worth your headphones.”'],
   atoms:[['LS1','Paused episode on the first face','Read existing singleton player + PodcastListens by owner; choose actual paused item and position. Do not build another player/progress store. Metadata-ready seek, expiry, owner switch and new episode selection get explicit acceptance.'],['LS2','Transport and persistence','Surface existing provider capabilities; do not imply lock-screen playback until iPhone proof. Pause/seek/rate/interruption/source failure stay coherent. Save accepted position with pending/failure handling; resume does not auto-play on arrival.'],['LS3','Real transcript / short segment','Inspect actual supplied transcripts/timestamps before creating UI. Authored segment range + whole-episode duration; no six-minute random cut labelled a chapter. Remove nothing when metadata is absent.'],['LS4','Programme truth','Keep all current shows/audio/video. De-duplicate exact lead; fix media-kind duration labels and false “new podcasts will land” when the real problem is no short episode. Programme/source ordering replaces unsupported ranking claims.'],['LS5','Watch lifecycle','One real player, correct source, actual playing event, stop on departure; caption/source fallback. Error 100/101/150 semantics checked against current official docs before building.'],['LS6','Timestamp travels','Exact public episode/source + known time → editable composer → accepted conversation → seek after metadata. Never embed her listening history or infer mood from a show.'],['LS7','Time lens joins Listen','Good life queries genuinely fitting episode/segment duration. If nothing fits, give a real longer option with explicit length or another action; do not pretend a 45-minute episode fits five minutes.']],
   first:'LS1 — paused episode console using the existing player.',
   states:'Never played / paused / playing / buffering / seek before metadata / unknown duration / external show / expired media / no timed transcript / interrupted phone audio.'},
  {id:'books',name:'Books',title:'The next chapter, with company',species:'Jasmine',material:'Approved reading table → chapter leaf → shelf register → club correspondence',pair:'Today’s chapter / Choose a book; literal direct actions retain the existing chapter/chooser.',
   order:['Your actual serial chapter and place','Complete monthly chapter index and low-capacity choices','This month’s free full book','Your real shelf and status controls','The actual current club and safe checkpoint','Alternates, reading preference and library door'],
   why:'The personal next page leads; a monthly book and a shared club are separate real identities. Company follows the reading rather than replacing it with a generic social feed.',
   setup:'No shelf filler. No status guessed from opening a book. First-use reading preference remains optional and its device-only storage is stated. Book/edition/chapter are the key; an incompatible edition does not inherit a spoiler unlock.',
   anatomy:[['Chapter leaf','Real serial title, chapter title/number, excerpt and stored place. Read goes straight to that chapter. Previously and backlog stay as currently directed; silent-backlog remains Halli’s decision. No replacement by a progress scoreboard.'],['Index / capacity','All released and future chapters remain with accurate labels. Next opens only when the existing rule allows. Re-read, shortest waiting chapter and “Just a page” keep their real destinations. Permission copy becomes shorter, not another repeated paragraph.'],['Monthly full book','Real monthly title/author and public-domain edition, Start / Resume, shelf status, Plan a time and Talk about it. Its cover is distinguishable from the serial. Existing alternates/reveal dates/library remain.'],['Shelf register','Reading / Want / Finished / Set aside are actual canonical UserBook states. Switching an already-shelved book must update status rather than silently deduplicate. Show actual pending/failure state, then confirmed readback.'],['Club correspondence','Live BookClubPick controls title and checkpoints consistently across Today, Books and Community. Label book/edition/reached boundary before discussion. No preview or notification excerpt leaks past that boundary.'],['Calendar / return','Chosen time creates existing PlannerItems source/ref to the exact edition or checkpoint; reschedule retains notes and provenance. Return opens that book/checkpoint. Six-week batch reports partial success and resists repeat duplication.']],
   craft:'Keep the approved table untouched. One bookmark points to current chapter, a quiet spine rule carries the index, the shelf is a register and club is correspondence. A small turned-book fragment can sit by alternates only if it adds a compositional pause; no repeated book pictures under every heading.',
   copy:['“Just one more chapter. Famous last words.”','“Your place is kept.” — only when stored','“Want / Reading / Finished / Set aside” remain clear'],
   atoms:[['BK1','One current club truth','Reconcile SEED_PICK fallback with actual BookClubPick across Books/Today/Community. Real missing/unpublished pick is distinct from loading. Test a changed pick with old shelf/progress still intact.'],['BK2','Shelf transition actually changes','Existing UserBook add/update adapter must distinguish new record from Reading transition. Await write, preserve old status on failure and notify shared consumers. Never make a fifth book system.'],['BK3','Chapter placement and completion','Keep serial/edition/chapter identities separate; verify reader close/settings/marks during animation and immediate glance refresh. Opening, fast skim and completion are different; do not broaden existing reach semantics accidentally.'],['BK4','Spoiler-safe same edition','Checkpoint access follows the real reached chapter + edition. Different edition, abandoned book, deleted comment, blocked author and notification excerpt all keep the gate. Reuse existing club/checkpoint infrastructure.'],['BK5','Plan and return','Chosen date/time/minutes → accepted Planner row → exact edition/checkpoint. Batch six weeks with dedup + partial-failure repair, not a second click creating six duplicates.'],['BK6','Reading to conversation','Reached public checkpoint → editable reflection → book club post → accepted DM → same checkpoint/book. Her private marginal note is never auto-published.'],['BK7','Small-capacity and voice','Retain all routes but replace duplicated generic permission paragraphs with useful source-specific lines. Backlog count versus silence and notification nudge remain Halli’s open choices.']],
   first:'BK1 / BK2 source consistency and real shelf transition before further ornament.',
   states:'New reader / saved chapter / unreleased chapter / existing shelf entry / changed club pick / different edition / failed status save / partial six-week plan / exhausted reading capacity.'},
  {id:'good',name:'Good life',title:'Minutes become something worth doing',species:'Marigold',material:'Daylight linen → a useful time choice → small joy slips → eleven open rooms',pair:'Time for yourself / A small joy; choose a real activity close to its direct action.',
   order:['A few minutes / fifteen / a whole evening','One genuinely fitting read, listen or do option','A chosen joy with Do now / Plan a time','All existing joys and permission lines','Eleven readable whole-life doors'],
   why:'Move from available time to a concrete action. Reading should not be the only answer to spare time. All eleven domains remain directly accessible without another preference maze.',
   setup:'Time is an explicit choice, not inferred energy or a calendar claim. No clinical mood questionnaire to unlock fun. Default is a practical suggestion from real content; unknown duration cannot qualify as “fits five minutes”. An activity can be kept, planned or done: three different states.',
   anatomy:[['Time control','Three labelled choices with dark active foreground, pressed semantics and no clipped support. Changing time updates the actual candidates in place. Keep the choice while a planner write fails.'],['Useful candidate','Readable actual title + verified time + short instruction. Direct Read/Play/Do button does that thing. Missing short media says “No short listen in this set”, rather than pretending podcasts do not exist. Full source/Why remains optional depth.'],['A chosen activity','A white linen slip with one useful instruction and primary Do now. Plan a time reveals compact date/time beside that activity or seeds the existing calendar sheet; choose after phone comparison. Save is not Done. No invisible default 21:00 placement.'],['Accepted plan','The same activity face reads back Tomorrow · 18:30 with Edit and a exact Planner return. The server-accepted date/time is the truth, not draft values. Conflict/failure retains the draft and leaves the activity available.'],['Small joys','Retain wander/duvet/market/meeting/poem and permission lines, but their real actions appear on the face where possible. Three repeated “no streaks” speeches do not teach the action. Genuine Why/citations stay reachable.'],['Eleven doors','Mirror, Move, Kindred, Curious, Delight, Nest, Tonight, Becoming, Make, Outside, Money. Two columns where labels fit, descriptions wrap; no 11px clipped mini-copy. Room states/useful routes need their own later inventory, not pretend blank previews.']],
   craft:'The time choice is horizontal and compact; activity is a linen work slip; joys are smaller open notes; doors are a readable directory. One marigold petal meets the action edge and a subtle seam continues to the room list. No repeated calendar art or ornamental countdown.',
   copy:['“A little room in your day.”','“Do it now” / “Plan a time”','“Some things are worth doing badly, just for fun.”'],
   atoms:[['GL1','Honest fit by minutes','Actual duration or authored segment range determines eligible content. Unknown is not short. Keep full set available with accurate longer labels; no generic phase-only picking.'],['GL2','Do / keep / plan are different','Existing joy/slip handler outcome and interface verbs agree. Doing can record progress only when chosen; planning creates a plan; keep stores the real object where supported. No tap-to-open secretly marks done.'],['GL3','A real chosen time','PlannerItems chosen date/time/minutes + exact activity provenance, dedup and pending/failed/success states. Preserve draft. Calendar opens the same exact object and returns without losing the selected time lens.'],['GL4','Activity speaks back','After accepted planning, original face reads the actual plan with Edit; Today and Planner agree. Completion reads back to Garden only from a real action, not a schedule row.'],['GL5','Readable room doorway','All eleven routes verified individually after real source inventory. Descriptions wrap at360/390/430 and target stays ≥44px; no scrolling chip clipping as the only way to find Money.'],['GL6','A shared plan, later','Reuse existing Community room/consented DM. An explicit invitation may contain public activity + selected proposed time; “suggested” and “accepted” are separate. No social RSVP capability claimed before real infrastructure audit.'],['GL7','Permission and useful depth','Shorten interface boilerplate, preserve instructions/source evidence. Reflection and Jess carry the real activity plus her question. No deterministic “your phase asks for” instruction.']],
   first:'GL1 / GL3 — time-fit choice and genuine chosen-time confirmation.',
   states:'Few minutes / long evening / no fitting audio / unknown duration / unscheduled / draft / saving / failed / confirmed / already planned / deliberately completed.'},
  {id:'yours',name:'Yours',title:'A drawer that remembers the source',species:'Forget-me-not',material:'Archive leaves → one real return → a mixed index → optional collections',pair:'Open your saves / Continue reading; real no-continuation state gets a useful honest alternative.',
   order:['One useful actual continuation, if stored','Real keeps across both existing origins','Mixed source-labelled index with optional filters/search','Complete existing kind collections','Clearly separate recommended phase set'],
   why:'Her objects lead, not a recommendation disguised as a save. Mixed keeps provide a quick route back; type filters help only when there is enough real content. No obligatory category-click before opening an item.',
   setup:'Profile saved IDs and SavedItems are reconciled without migration/deletion. Some profile IDs have no saved date: label them undated, never “kept today”. Empty and failed-to-load differ. Missing/deleted source retains its remembered object and Retry where recovery is possible.',
   anatomy:[['Useful return','One exact unfinished object with its real reader/page/episode state. No continuation exists: begin directly with actual keeps. A bookmark marker means a stored place; a forget-me-not marks collection continuity, not an invented personal souvenir.'],['Archive entry','Title, content kind, source/version, real saved date if available, short genuine excerpt and direct Open / Resume / Play. Unknown kinds remain visible with appropriate source/error handling. One removal control is separate from opening.'],['Mixed versus grouped','Recent dated items can be mixed in one reading lane. Existing categories remain available; filter/search only narrows, never deletes or migrates. Undated legacy keeps stay in their own truthful group. Empty search preserves other collections.'],['Annotations','Her own note is shown only from real stored content and clearly distinguished from source text. Quote/version context lets an exact passage return survive revised content. Unmatched passage stays recoverable. No AI narrative about why she saved it.'],['Removal / failure','Pending disables only the affected object, retains old view on failure and reports partial store success honestly. If destructive removal needs confirmation, use the existing recovery contract. Do not advertise Undo without an actual reversible operation.'],['Recommendations','Keep the current phase set, explicitly separate from saved things. It never inflates saved count or pretends she chose it. Whole-life subject relevance still comes from actual interest/history, not a clinical default.']],
   craft:'Different sizes earn different jobs: one bookmarked return, then a narrow index with aligned provenance; category dividers use quiet archive leaf edges. No flower wallpaper, scrapbook clutter or fabricated dates. An occasional pressed outline can identify a saved section, not every item.',
   copy:['“Good things, kept close.”','“No date kept for this one.”','“The source moved. Your note is still here.” — only when retained'],
   atoms:[['YR1','One complete actual collection','Pagination and exact-ID lookups retain Profile saved IDs + SavedItems across every type. Counts mean real owner keeps, not loaded-window rows; failures/unknown kinds survive. No third store.'],['YR2','Dates, duplicates and provenance','Dedup actual object/version across origins; preserve different annotations where meaningful. Dated sorting excludes invented dates; undated IDs remain. Version supersession does not silently rewrite a kept edition.'],['YR3','One direct useful return','Article paragraph only when anchored, episode seek after metadata, book edition/chapter, lesson exact version, activity exact plan. Deleted sources expose stored title/context and recovery rather than a broken link.'],['YR4','Private versus public at the object','Source and selected passage can travel explicitly; her note, chart/cycle and save history do not travel by default. Recipient source availability is independent of sender’s access. Never expose owner IDs publicly.'],['YR5','Removal without lies','Await both applicable existing-origin updates; partial failure retains unresolved origin and visible Retry. Keep source/read position independent from removal. No false success or invented undo.'],['YR6','Small versus large archive','No filters required for one item. At larger counts, optional search/type filtering preserves direct object opens and focused pair. Recommendations remain a distinct final band.'],['YR7','Returns from social / Planner / Jess','Safe exact reference resolution plus owner checks for private notes; rejected/deleted/blocked/unknown reference gets useful source state. Each adapter reuses existing stores and dispatchers; no generic Lifestyle landing substitutes.']],
   first:'YR2 / YR3 — honest dated provenance and exact mixed-object returns.',
   states:'Empty / one item / undated legacy IDs / many kinds / old edition / duplicate origins / unknown source / private note / failed removal / blocked conversation / no entitled source.'}
];

function inline(s){ return esc(s).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\[([^\]]+)\]\((https:\/\/[^)]+)\)/g,'<a href="$2" target="_blank" rel="noreferrer">$1</a>'); }
function markdown(md){
  const lines=md.split(/\r?\n/); let html='',i=0;
  while(i<lines.length){const l=lines[i]; if(!l.trim()){i++;continue;}
    if(l.startsWith('|')){let rows=[];while(i<lines.length&&lines[i].startsWith('|'))rows.push(lines[i++].split('|').slice(1,-1).map(c=>c.trim()));const heads=rows[0];html+='<div class="audit-grid">'+rows.slice(2).map(row=>'<article><h3>'+inline(row[0])+'</h3>'+row.slice(1).map((c,j)=>'<p><b>'+inline(heads[j+1]||'Detail')+'</b><br>'+inline(c)+'</p>').join('')+'</article>').join('')+'</div>';continue;}
    if(/^#{1,6} /.test(l)){const n=Math.min(3,l.match(/^#+/)[0].length+1);html+=`<h${n}>${inline(l.replace(/^#+ /,''))}</h${n}>`;i++;continue;}
    if(/^[-*] /.test(l)){html+='<ul>';while(i<lines.length&&/^[-*] /.test(lines[i]))html+='<li>'+inline(lines[i++].slice(2))+'</li>';html+='</ul>';continue;}
    html+='<p>'+inline(l)+'</p>';i++;
  } return html;
}
const css=`
@font-face{font-family:Editorial;src:url(https://fonts.gstatic.com/s/cormorantgaramond/v21/co3bmX5slCNuHLi8bLeY9MK7whWMhyjYpHtKky2F7i6C.woff2);font-style:normal;font-weight:400 700;font-display:swap}
@font-face{font-family:Editorial;src:url(https://fonts.gstatic.com/s/cormorantgaramond/v21/co3ZmX5slCNuHLi8bLeY9MK7whWMhyjYrEtImSqn7B6D.woff2);font-style:italic;font-weight:400 700;font-display:swap}
:root{--ground:#F5F4F1;--white:#fff;--ink:#191510;--muted:#51444E;--heading:#7A1A12;--gold:#A8893F;--line:#EAE7E0;--sage:#8FAF8F;--ui:ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif;--serif:Editorial,Georgia,serif}
*{box-sizing:border-box}body{margin:0;background:var(--ground);color:var(--ink);font:500 18px/1.55 var(--serif)}main{max-width:980px;margin:auto;padding:22px 22px 70px}a{color:var(--muted);text-underline-offset:4px;overflow-wrap:anywhere}button,input,textarea,select{font:600 14px/1.4 var(--ui)}button,a.control,summary,input,select{min-height:44px}button{border:1px solid var(--line);border-radius:10px;background:white;color:var(--ink);padding:10px 14px;cursor:pointer}button:disabled{opacity:.55;cursor:default}button.primary{background:var(--muted);border-color:var(--muted);color:white}button[aria-pressed=true]{background:#ECE7DA;color:var(--ink);border-color:var(--gold)}button:focus-visible,a:focus-visible,summary:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--muted);outline-offset:4px}button:active{transform:translateY(1px)}[hidden]{display:none!important}h1,h2,h3,h4{color:var(--heading);font-weight:600;line-height:1.2}h1{font-size:clamp(44px,9.5vw,56px);font-style:italic;font-weight:400;margin:18px 0 14px}h2{font-size:clamp(27px,6.4vw,34px);font-style:italic;margin:22px 0 14px}h3{font-size:20px;font-style:italic;margin:0 0 10px}h4{font-size:18px;margin:0 0 8px}p{margin:8px 0 14px}nav{display:flex;justify-content:space-between;gap:14px;font:600 13px/1.4 var(--ui)}nav a{display:inline-flex;align-items:center;min-height:44px}.eyebrow,.micro{font:600 12px/1.4 var(--ui);letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}.caption{font:500 13px/1.4 var(--ui);color:var(--muted)}.lede{font-size:20px;max-width:660px}.flags{display:flex;gap:10px;flex-wrap:wrap;font:600 13px/1.4 var(--ui)}.flags span{border-bottom:1px solid var(--gold);padding:8px 0}.room-choices{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px;margin:22px 0}.room-choices button{min-height:50px}.overview{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin:22px 0}.flow{list-style:none;padding:0;margin:0;border-left:1px solid var(--gold)}.flow li{position:relative;padding:8px 0 8px 18px;border-bottom:1px solid var(--line);font-size:17px}.flow li:before{content:'';width:6px;height:6px;border-radius:50%;background:var(--gold);position:absolute;left:-3px;top:20px}.spec{border-top:1px solid var(--line);padding:18px 0;margin-top:18px}details{border-top:1px solid var(--line);padding:8px 0;margin-top:18px}summary{cursor:pointer;display:list-item;padding:12px 0;font:600 14px/1.4 var(--ui);color:var(--muted)}.anatomy,.audit-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.anatomy article,.audit-grid article{border-top:1px solid var(--line);padding-top:14px;min-width:0}.anatomy p,.audit-grid p{font-size:17px;overflow-wrap:anywhere}code{font:500 13px/1.4 var(--ui);overflow-wrap:anywhere}.atoms{display:grid;grid-template-columns:1fr 1fr;gap:18px}.atom{border-left:1px solid var(--gold);padding-left:14px}.atom p{font-size:17px}.atom .eyebrow{margin-bottom:8px}.study{position:relative;isolation:isolate;background:white;border:1px solid var(--line);border-radius:0 0 18px 18px;padding:22px;margin:18px 0}.study .caption{margin-bottom:18px}.study-title{font-size:20px;font-style:italic}.study-actions{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.study-output{border-top:1px solid var(--line);padding-top:14px;margin-top:18px}.study-output p:last-child{margin-bottom:0}.lesson-number{font:600 13px/1.4 var(--ui);float:right}.note-box{width:100%;min-height:86px;padding:14px;border:1px solid var(--line);border-radius:10px;font:500 17px/1.5 var(--serif);margin:8px 0}.lesson-stage{padding-top:14px;border-top:1px solid var(--gold)}.study-sky:before{content:'';position:absolute;right:10px;top:10px;width:40px;height:40px;border-top:1px solid var(--gold);border-right:1px solid var(--gold);border-radius:50%;pointer-events:none;z-index:-1}.bookmark-strip{border-left:4px solid var(--muted);padding:10px 14px;background:var(--ground)}.passage{padding:18px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.passage.marked{border-left:2px solid var(--gold);padding-left:14px}.transport{display:flex;align-items:center;gap:14px;padding:18px 0;border-bottom:1px solid var(--line)}.transport button{border-radius:999px;min-width:90px}.sample-rail{flex:1;height:4px;background:var(--line);position:relative}.sample-rail:after{content:'';position:absolute;left:0;top:0;height:4px;width:28%;background:var(--muted)}.spine-row{display:grid;grid-template-columns:22px 1fr;gap:14px}.spine{border-left:3px solid var(--gold);writing-mode:vertical-rl;font:600 12px/1.4 var(--ui);color:var(--muted);padding:8px 0}.checkpoint{margin-top:18px;border-top:1px solid var(--line);padding-top:14px}.time-options{display:flex;gap:8px}.time-options button{flex:1;padding:10px}.timeform{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:block;font:600 13px/1.4 var(--ui)}label input,label select{display:block;width:100%;margin-top:8px;padding:10px;min-width:0;border:1px solid var(--line);border-radius:8px;background:white;color:var(--ink)}.archive-entry{display:grid;grid-template-columns:30px 1fr;gap:14px;align-items:start;margin-top:14px;border-top:1px solid var(--line);padding-top:14px}.archive-index{font:600 12px/1.4 var(--ui);padding-top:5px;color:var(--muted)}.swatch{display:inline-block;width:22px;height:22px;border:1px solid var(--line);vertical-align:middle;margin-right:8px}.rules{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.rules p{font-size:17px}.callout{border-left:2px solid var(--gold);padding:8px 0 8px 14px}.stage-label{font:600 13px/1.4 var(--ui);color:var(--muted)}footer{font:500 13px/1.4 var(--ui);margin-top:26px;color:var(--muted)}.control{display:inline-flex;align-items:center;padding:10px 0;font:600 14px/1.4 var(--ui)}@media(max-width:680px){main{padding:18px 18px 60px}.room-choices{grid-template-columns:repeat(3,minmax(0,1fr))}.overview,.anatomy,.audit-grid,.atoms,.rules{grid-template-columns:1fr}.overview{gap:18px}.study{padding:18px}.time-options{flex-wrap:wrap}.time-options button{flex:1 1 80px}.lede{font-size:18px}.timeform{gap:10px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important;animation:none!important}button:active{transform:none}}
`;
function study(r){
  const stamp='<p class="caption">Local interaction study · sample objects and positions · no account writes, audio, posts or DMs</p>';
  if(r.id==='sky')return `<div class="study study-sky" data-study="sky">${stamp}<div class="eyebrow">A little sky wisdom <span class="lesson-number" id="lesson-num">1 / 2 sample lessons</span></div><div class="lesson-stage"><h3 id="lesson-title">That steady light might be a planet</h3><p id="lesson-body">Bright planets tend to shine steadily, while stars often flicker. A useful first clue, not a verdict.</p><button data-action="help" aria-expanded="false">Why the flicker?</button><p id="lesson-help" hidden>Earth’s moving air bends distant starlight. A planet’s wider apparent disc can average some of that disturbance.</p><div class="study-actions"><button data-action="lesson-back" disabled>Previous lesson</button><button data-action="lesson-next">Next lesson</button><button data-action="lesson-keep" aria-pressed="false">Keep this</button><button data-action="lesson-note" aria-expanded="false">A private note</button></div><div id="lesson-note" hidden><label for="sample-note">Your sample note</label><textarea class="note-box" id="sample-note" placeholder="One line, if you fancy it."></textarea><button data-action="note-state">Try saved-note state</button></div></div><div class="study-output" aria-live="polite"><p id="study-status">Current lesson stays visible; help opens here, with no new destination.</p></div></div>`;
  if(r.id==='read')return `<div class="study" data-study="read">${stamp}<div class="bookmark-strip"><span class="eyebrow">Sample stored place</span><h3>The Difference Between Being Kind and Being Scared</h3><p class="caption">FemWell Editorial · illustrative saved passage</p><button class="primary" data-action="read-resume">Resume this passage</button></div><div class="passage" id="sample-passage"><p>People-pleasing looks like kindness from the outside. From the inside, it’s a fear response — and most women have been doing it so long they don’t recognise the difference.</p></div><div class="study-actions"><button data-action="read-keep" aria-pressed="false">Keep this read</button><button data-action="read-error">Try a failed save</button></div><div class="study-output" aria-live="polite"><p id="study-status">Resume highlights the illustrative passage. It does not mark the article finished.</p></div></div>`;
  if(r.id==='listen')return `<div class="study" data-study="listen">${stamp}<span class="eyebrow">Sample paused episode</span><h3>Mel Giedroyc and AJ Odudu</h3><p>Body confidence, reinvention and female friendship.</p><p class="caption">How To Fail With Elizabeth Day · actual source title, illustrative position</p><div class="transport"><button class="primary" data-action="listen-play" aria-pressed="false">Resume</button><div class="sample-rail" aria-hidden="true"></div><span class="caption">12:40</span></div><div class="study-actions"><button data-action="listen-buffer">Try buffering</button><button data-action="listen-source">Try source failure</button><button data-action="listen-transcript" aria-expanded="false">Transcript state</button></div><p id="sample-transcript" hidden>No supplied timed transcript in this sample. A synopsis must never pretend to be one.</p><div class="study-output" aria-live="polite"><p id="study-status">A real implementation reuses the existing player and saved position; this study has no audio.</p></div></div>`;
  if(r.id==='books')return `<div class="study" data-study="books">${stamp}<div class="spine-row"><div class="spine">BOOK CLUB · ONE EDITION</div><div><span class="eyebrow">Illustrative checkpoint</span><h3>Little Women · the first Christmas</h3><p>Each sister carries the hard winter differently. Which one did you recognise?</p><p class="caption">Sample reader is before this checkpoint. Actual chapter boundaries must come from the live pick and edition.</p></div></div><div class="checkpoint"><button data-action="book-open">Preview checkpoint</button><button data-action="book-reached" aria-pressed="false">Try reached state</button><div class="study-output" aria-live="polite"><p id="study-status">Discussion is locked in this sample. Opening a book is not reaching its checkpoint.</p></div></div></div>`;
  if(r.id==='good')return `<div class="study" data-study="good">${stamp}<span class="eyebrow">A little room in your day</span><div class="time-options"><button data-action="time-5" aria-pressed="true">5 minutes</button><button data-action="time-15" aria-pressed="false">15 minutes</button><button data-action="time-evening" aria-pressed="false">An evening</button></div><h3 id="activity-title" style="margin-top:18px">Read one poem out loud</h3><p id="activity-line">To no one. An audience is optional.</p><div class="study-actions"><button data-action="activity-now">Try doing state</button><button data-action="activity-plan" aria-expanded="false">Plan a time</button></div><div id="time-draft" hidden><div class="timeform"><label>Sample day<select id="plan-day"><option>Tomorrow</option><option>Saturday</option></select></label><label>Sample time<input id="plan-time" type="time" value="18:30"></label></div><div class="study-actions"><button data-action="plan-confirm">Try confirmed state</button><button data-action="plan-error">Try failed save</button></div></div><div class="study-output" aria-live="polite"><p id="study-status">A chosen plan returns to this same activity. Planning is not completion.</p></div></div>`;
  return `<div class="study" data-study="yours">${stamp}<span class="eyebrow">One exact keepsake</span><div class="archive-entry"><span class="archive-index">01</span><div><h3>Our star has no solid floor</h3><p class="caption">Sky lesson · edition 1 · saved date unknown in this sample</p><button data-action="archive-open">Preview exact return</button><button data-action="archive-revised">Try revised source</button><button data-action="archive-remove-error">Try failed removal</button></div></div><div class="study-output" aria-live="polite"><p id="study-status">The saved edition stays distinct from today’s rotating deck.</p></div></div>`;
}
function roomHtml(r){return `<section class="room" id="room-${r.id}" ${r.id==='sky'?'':'hidden'} aria-labelledby="title-${r.id}"><div class="eyebrow">${esc(r.name)} · ${esc(r.species)}</div><h2 id="title-${r.id}">${esc(r.title)}</h2><p>${esc(r.material)}</p><a class="control" href="/SkyWorldsDemo?direction=petal-press&amp;section=${r.id}">Open the current ${esc(r.name)} preview</a><div class="overview"><div><h3>The page, in order</h3><ol class="flow">${r.order.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></div><div><h3>Why this order</h3><p>${esc(r.why)}</p><p class="caption">Focused actions: ${esc(r.pair)}</p><div class="callout"><span class="eyebrow">First small build</span><p>${esc(r.first)}</p></div></div></div><h3>Try one small behaviour</h3>${study(r)}<details><summary>Setup, first use &amp; returning</summary><p>${esc(r.setup)}</p><p><strong>State coverage:</strong> ${esc(r.states)}</p></details><details><summary>Every movement · layout, controls &amp; wording</summary><div class="anatomy">${r.anatomy.map(([a,b])=>`<article><h3>${esc(a)}</h3><p>${esc(b)}</p></article>`).join('')}</div><h3>Material continuity</h3><p>${esc(r.craft)}</p><h3>Voice examples</h3><ul>${r.copy.map(c=>`<li>${esc(c)}</li>`).join('')}</ul></details><details><summary>${r.atoms.length} build atoms · data, returns &amp; failure cases</summary><div class="atoms">${r.atoms.map(([id,t,d])=>`<article class="atom"><div class="eyebrow">${id} · proposed</div><h3>${esc(t)}</h3><p>${esc(d)}</p><p class="caption">Before build: re-brainstorm this atom, verify its real fields and existing handler, then prove pending/error/no-auth/return at 360 / 390 / 430.</p></article>`).join('')}</div></details></section>`;}
const interactions=`
const nav=document.querySelector('.room-choices');
nav.addEventListener('click',e=>{const b=e.target.closest('button[data-room]');if(!b)return;document.querySelectorAll('.room').forEach(r=>r.hidden=r.id!=='room-'+b.dataset.room);nav.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('room-state').textContent=b.textContent+' body proposal · header approved · not promoted';history.replaceState(null,'','#'+b.dataset.room);});
const lessonData=[['That steady light might be a planet','Bright planets tend to shine steadily, while stars often flicker. A useful first clue, not a verdict.'],['Our star has no solid floor','The Sun is a ball of hot plasma. Its visible surface is a layer we can see, not solid ground.']];let lessonIndex=0;const lessonKeeps=[false,false],lessonNotes=['',''];let bookReached=false;
document.addEventListener('input',e=>{if(e.target.id==='sample-note')lessonNotes[lessonIndex]=e.target.value;});
document.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b)return;const root=b.closest('[data-study]'),q=s=>root.querySelector(s),say=s=>q('#study-status').textContent=s;const a=b.dataset.action;
if(a==='help'){const p=q('#lesson-help');p.hidden=!p.hidden;b.setAttribute('aria-expanded',String(!p.hidden));}
if(a==='lesson-next'||a==='lesson-back'){lessonIndex=a==='lesson-next'?1:0;q('#sample-note').value=lessonNotes[lessonIndex];q('#lesson-title').textContent=lessonData[lessonIndex][0];q('#lesson-body').textContent=lessonData[lessonIndex][1];q('#lesson-num').textContent=(lessonIndex+1)+' / 2 sample lessons';q('[data-action=lesson-back]').disabled=lessonIndex===0;q('[data-action=lesson-next]').disabled=lessonIndex===1;q('[data-action=lesson-keep]').textContent=lessonKeeps[lessonIndex]?'Kept in this study':'Keep this';q('[data-action=lesson-keep]').setAttribute('aria-pressed',String(lessonKeeps[lessonIndex]));q('[data-action=help]').hidden=lessonIndex!==0;q('#lesson-help').hidden=true;q('[data-action=help]').setAttribute('aria-expanded','false');say('Lesson '+(lessonIndex+1)+' opens in the same clearing. Each sample lesson keeps its own draft in this open study.');}
if(a==='lesson-keep'){lessonKeeps[lessonIndex]=!lessonKeeps[lessonIndex];b.setAttribute('aria-pressed',String(lessonKeeps[lessonIndex]));b.textContent=lessonKeeps[lessonIndex]?'Kept in this study':'Keep this';say(lessonKeeps[lessonIndex]?'Local kept state for this exact sample lesson. No account save was made.':'Local kept state removed. The other sample lesson keeps its own state.');}
if(a==='lesson-note'){const p=q('#lesson-note');p.hidden=!p.hidden;b.setAttribute('aria-expanded',String(!p.hidden));}
if(a==='note-state'){say(q('#sample-note').value.trim()?'Sample note retained in this open study only. Production must acknowledge its owner-private write and exact return.':'Add a sample line first; an empty note is not saved.');}
if(a==='read-resume'){const p=q('#sample-passage');p.classList.add('marked');p.setAttribute('tabindex','-1');p.focus({preventScroll:true});p.scrollIntoView({block:'nearest',behavior:'auto'});say('This illustrative passage is reached directly; completion stays unchanged.');}
if(a==='read-keep'){const kept=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(kept));b.textContent=kept?'Kept in this study':'Keep this read';say(kept?'Local confirmed-state illustration. The real action must await the existing save write.':'Local keep removed; actual reading place is independent.');}
if(a==='read-error'){say('Failed-save illustration: the intended change did not save. The prior confirmed keep state is unchanged; the article and intended action remain available for Retry.');}
if(a==='listen-play'){const playing=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(playing));b.textContent=playing?'Pause':'Resume';say(playing?'Playing-state illustration only; no audio. Actual playback must confirm the playing event before showing this state.':'Paused-state illustration. The real current time belongs to the singleton player.');}
if(a==='listen-buffer'){q('[data-action=listen-play]').setAttribute('aria-pressed','false');q('[data-action=listen-play]').textContent='Resume';say('Buffering-state illustration: transport is not playing; keep title and position visible. A requested play is not audible playback.');}
if(a==='listen-source'){q('[data-action=listen-play]').setAttribute('aria-pressed','false');q('[data-action=listen-play]').textContent='Retry';say('Source-failure illustration: not playing. Keep saved position, Retry and the real source link. Do not mark listened.');}
if(a==='listen-transcript'){const p=q('#sample-transcript');p.hidden=!p.hidden;b.setAttribute('aria-expanded',String(!p.hidden));}
if(a==='book-open'){say(bookReached?'Reached-state preview: this checkpoint’s discussion can open; later checkpoints remain protected.':'Locked-state preview: reach this checkpoint in this edition first. No spoiler text is shown.');}
if(a==='book-reached'){bookReached=!bookReached;b.setAttribute('aria-pressed',String(bookReached));b.textContent=bookReached?'Try not-reached state':'Try reached state';say(bookReached?'Local reached state only. Real unlock follows the exact edition and reached chapter; no progress write was made.':'Sample checkpoint locked again. Private notes and later chapters are separate.');}
if(a.startsWith('time-')){root.querySelectorAll('[data-action^=time-]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const options={'time-5':['Read one poem out loud','To no one. An audience is optional.'],'time-15':['Move one thing back','Put it where it makes you happy.'],'time-evening':['A duvet and a stack of books','Leave the evening open.']};q('#activity-title').textContent=options[a][0];q('#activity-line').textContent=options[a][1];q('#time-draft').hidden=true;q('[data-action=activity-plan]').setAttribute('aria-expanded','false');say('The sample activity changes with the explicit time choice. No inferred energy or calendar promise.');}
if(a==='activity-now'){say('Doing-state illustration. The real app records only the action she deliberately completed; opening or planning is not completion.');}
if(a==='activity-plan'){const p=q('#time-draft');p.hidden=!p.hidden;b.setAttribute('aria-expanded',String(!p.hidden));}
if(a==='plan-confirm'){if(!q('#plan-time').value){say('Choose a sample time first. No confirmation is shown for an empty time.');return;}say('Confirmed-state illustration: '+q('#plan-day').value+' · '+q('#plan-time').value+' · '+q('#activity-title').textContent+'. No Planner row was created.');}
if(a==='plan-error'){say('Failed-save illustration: the chosen day, time and activity remain in the draft. No “Planned” acknowledgement.');}
if(a==='archive-open'){say('Exact-return illustration: sun-surface · edition 1. Return opens this kept lesson, even if today’s deck has changed.');}
if(a==='archive-revised'){say('Revised-source illustration: retain the kept edition and note. If the passage moved, offer its preserved context and the revised source; never silently swap them.');}
if(a==='archive-remove-error'){say('Failed-removal illustration: the keepsake remains visible. A partial two-store removal must identify the unresolved origin and offer Retry.');}
});
const initial=location.hash.slice(1);const initialButton=document.querySelector('[data-room="'+initial.replace(/[^a-z]/g,'')+'"]');if(initialButton)initialButton.click();
`;
const html=`<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lifestyle · the detail workshop</title><style>${css}</style></head><body><main><nav><a href="/Ideas">Ideas · Dev</a><a href="/selected-lifestyle/index.html">The six current previews</a></nav><header><div class="eyebrow">6 October · founder’s section workshop</div><h1>The garden has a life.</h1><p class="lede">The headers are yours. Now give every section its own rhythm, useful details and proper connections.</p><div class="flags"><span>Six headers approved</span><span>Body proposals, not promoted</span><span>42 mapped work items</span></div><p class="caption">These small interactive studies demonstrate proposed behaviours. They use sample states, do not read your account and do not prove persistence or social wiring.</p></header><div class="room-choices" aria-label="Choose a section workshop">${rooms.map((r,i)=>`<button data-room="${r.id}" aria-pressed="${i===0}">${r.name}</button>`).join('')}</div><p id="room-state" class="stage-label" role="status">Sky body proposal · header approved · not promoted</p>${rooms.map(roomHtml).join('')}<section class="spec"><h2>The detail contract</h2><p>Every atom gets its own short brainstorm before it is built. These are proposals based on the existing pages and sources, not permission to rush 42 work items at once.</p><div class="rules"><div><h3>Looks &amp; reads</h3><p>At360px,18px outer inset leaves324px. One reading-padding owner. Heading role27–34; subsection20; title18; body16–17; captions13–14; controls14, with44px targets. Retain current Cormorant/Ephesis/system voices and clean alabaster/white ground.</p></div><div><h3>Does &amp; returns</h3><p>Define the literal verb, exact object/version, real handler and accepted outcome. Test one tap to consume or do, one return to the same object. Setup sheets keep drafts. Save, planned, playing, reached and done are separate states.</p></div><div><h3>Connects &amp; remembers</h3><p>Reuse existing stores, player, shelf, Planner, Community and consented DM. Public source may travel deliberately; private note stays separate. Today, Jess and Garden read actual accepted state. No parallel catalogues or invented recaps.</p></div></div><details><summary>Whole-app connections · explicit roles</summary><p><strong>Today:</strong> current actual chapter/episode/activity and exact return. <strong>Planner:</strong> chosen time, provenance and honest readback. <strong>Journal:</strong> owner-private source-linked notes. <strong>Community / DM:</strong> explicit public-object discussion, existing room and recipient consent, safe reply return. <strong>Garden:</strong> actual completion provenance, no streak.</p><p><strong>Jess:</strong> authored signal-based glance, source plus her question, no generated account biography. <strong>Profile:</strong> actual interests and preferences, owner-safe refresh. <strong>Health / Pulse:</strong> chosen context or genuine observations, never compulsory phase interpretation. <strong>Nutrition / Programs:</strong> only an actual recipe/practice relationship with its real source. <strong>Events:</strong> actual shared activity/event if it exists. <strong>Deals:</strong> relevant source-linked offers only, no forced shopping surface. <strong>Doctor Export:</strong> explicit relevant health records only; private reading taste and social history are not added as medical data.</p><p>Notifications reuse the existing dispatcher after a separate approved atom; the held reading nudge stays held. Some surfaces have no useful current relation to a particular atom. Record that deliberately rather than adding a generic button.</p></details><details><summary>Build sequence &amp; proof gates</summary><ol><li>Sky: lesson/help/exact-note return, then accepted action readbacks and public-object social round-trip.</li><li>Read: preserve article paragraphs and truthful saves, then genuine lead/continuation and selected-passage connection.</li><li>Listen: existing paused player, actual metadata/source states, then supplied transcript/timed reference.</li><li>Books: current club consistency and shelf status, then edition-safe checkpoint/Planner returns.</li><li>Good life: true time fit, actual chosen-time write and activity readback, then eleven room audits.</li><li>Yours: dates/provenance/returns, then archive ordering and exact social/private-note resolution.</li></ol><p>Each small build: current source inventory → cited options → real implementation → Ideas preview → native360/390/430 pixels and taps → adversarial P0/P1/P2 evidence → Bible/STATUS. Header acceptance is distinct from body approval and main promotion.</p></details></section><section class="spec"><h2>Evidence, when you want it</h2><p class="caption">The overview stays short. Full feature inventories, research, craft and failure cases live below.</p><details><summary>Fresh source inventory &amp; wiring gaps</summary>${fs.existsSync('claude-state/creative/section-detail-source.md')?markdown(fs.readFileSync('claude-state/creative/section-detail-source.md','utf8')):'<p>Source audit being finalised; no new implementation claimed.</p>'}</details><details><summary>Primary research &amp; options for every section</summary>${markdown(fs.readFileSync('claude-state/creative/section-detail-research.md','utf8'))}</details><details><summary>Creative thinking &amp; craft rejection tests</summary>${fs.existsSync('claude-state/creative/section-detail-craft.md')?markdown(fs.readFileSync('claude-state/creative/section-detail-craft.md','utf8')):'<p>Independent craft review being finalised.</p>'}</details><details id="checks"><summary>Checks, limits &amp; next work</summary><p id="workshop-proof">Planning artifact awaiting final native responsive/tap verification.</p><p>Current six-room production preview remains the prior230-check build. This workshop does not re-test account writes, assert age, send posts/DMs, change preferences, generate readings or promote main. Physical iPhone swipe, whole social graph and real persistence remain separate build proof.</p><p>Done this pass: accepted headers recorded, actual body inspection, complete source/craft/research pass, per-section composition and small state studies. Queued: atom-by-atom implementation and exact remote readback, beginning with Sky.</p></details></section><footer>FemWell · Ideas · Dev · Canon §10.5.17. One shared brand bible; no new functions, entities or parallel storage systems.</footer></main><script>${interactions}</script></body></html>`;
